// One bounded network operation, including response-body consumption. Preserve
// both the caller cancellation and any timeout/signal supplied by the SDK.
export function boundedFetch(fetcher: typeof fetch, parent?: AbortSignal, deadlineMs = 8000): typeof fetch {
  return (input, init) => {
    const signals: AbortSignal[] = [AbortSignal.timeout(deadlineMs)];
    if (parent) signals.push(parent);
    const initSignal = (init as { signal?: AbortSignal | null } | undefined)?.signal;
    if (initSignal) signals.push(initSignal);
    if (input instanceof Request) signals.push(input.signal);
    return fetcher(input, { ...init, signal: AbortSignal.any(signals) });
  };
}

type Caller = { rpc(name: string, args: Record<string, unknown>): PromiseLike<{ data: unknown; error: unknown }> };

// Invoke with the verified caller's Authorization header, never a service key.
// This reaches the authoritative Auth/session/member/device checks even when
// the protected handler subsequently uses a service client or external API.
export async function businessSessionAllowed(caller: Caller): Promise<boolean> {
  try { const {data,error}=await caller.rpc('business_session_allowed',{});return !error&&data===true; }
  catch { return false; }
}
export function guardBusinessRequest(
  handler: (request: Request) => Response | Promise<Response>,
  client: (request: Request) => Caller,
  shouldCheck: (request: Request) => boolean = request => request.method !== 'OPTIONS',
) {
  return async (request: Request): Promise<Response> => {
    if (shouldCheck(request) && !await businessSessionAllowed(client(request))) {
      return new Response(JSON.stringify({error:'Sign in again to continue.',code:'ACTIVE_SESSION_REQUIRED'}),{
        status:401,headers:{'Content-Type':'application/json','Cache-Control':'private, no-store, max-age=0',
          'CDN-Cache-Control':'no-store','Access-Control-Allow-Origin':'*','Access-Control-Allow-Headers':'authorization,apikey,x-client-info,content-type,range',
          'Access-Control-Allow-Methods':'POST,GET,HEAD,OPTIONS'},
      });
    }
    return handler(request);
  };
}

import { createClient } from 'npm:@supabase/supabase-js@2.112.3';
import { guardBusinessRequest } from './businessSessionGuard.ts';
import { boundedFetch } from './boundedFetch.ts';

export function serveBusinessRequest(handler: (request: Request) => Response | Promise<Response>, shouldCheck?: (request: Request) => boolean) {
  Deno.serve(guardBusinessRequest(handler, request => createClient(
    Deno.env.get('SUPABASE_URL')!,Deno.env.get('SUPABASE_ANON_KEY')!,{
      auth:{persistSession:false,autoRefreshToken:false},
      global:{headers:{Authorization:request.headers.get('Authorization')||''},fetch:boundedFetch(fetch,request.signal)},
    },
  ),shouldCheck));
}

import { CrispHopError, PAYMENT_FIELDS, matchesReceipt, outcome, persistOutcome, recoverPayment, requestCrisp } from "./paymentRecovery.ts";
import type { Dependencies, Payment } from "./paymentRecovery.ts";

const cors = { "Access-Control-Allow-Origin": "*", "Access-Control-Allow-Methods": "POST, GET, OPTIONS", "Access-Control-Allow-Headers": "authorization, apikey, x-client-info, content-type" };
const json = (data: unknown, status = 200) => new Response(JSON.stringify(data), {
  status, headers: { ...cors, "Content-Type": "application/json", "Cache-Control": "no-store" },
});
const uuid = (value: unknown) => typeof value === "string" && /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(value);
const keyValid = (value: unknown) => typeof value === "string" && /^[a-zA-Z0-9:_-]{8,128}$/.test(value);
function sameIntent(prior: Payment, body: any) {
  return prior.recipient_id === body.recipient_id && prior.conversation_id === body.conversation_id &&
    Number(prior.amount) === Number(body.amount) && prior.currency === (body.currency ?? "USD") &&
    (prior.note ?? null) === (body.note ?? null) && (prior.listing_id ?? null) === (body.listing_id ?? null) && (prior.order_id ?? null) === (body.order_id ?? null);
}
export function createBridgeHandler(deps: Dependencies) {
  return async (req: Request): Promise<Response> => {
    if (req.method === "OPTIONS") return new Response("ok", { headers: cors });
    let inFlight: Payment | null = null;
    try {
      const token = (req.headers.get("Authorization") || "").replace(/^Bearer\s+/i, "").trim();
      if (!token) return json({ success: false, error: "Unauthorized" }, 401);
      const { data: authData, error: authErr } = await deps.db.auth.getUser(token);
      const user = authData?.user;
      if (authErr || !user) return json({ success: false, error: "Unauthorized" }, 401);
      const url = new URL(req.url);
      const action = url.searchParams.get("action") || "";
      if (req.method === "GET" && action === "payment-status") {
        const id = url.searchParams.get("payment_id");
        const key = url.searchParams.get("idempotency_key");
        if ((id && !uuid(id)) || (key && !keyValid(key)) || (!id && !key)) return json({ success: false, error: "Valid payment_id or idempotency_key required" }, 400);
        let query = deps.db.from("chat_payments").select(PAYMENT_FIELDS).eq("sender_id", user.id);
        if (id) query = query.eq("id", id);
        if (key) query = query.eq("idempotency_key", key);
        const { data, error } = await query.maybeSingle();
        if (error) return json({ success: false, code: "PAYMENT_STATUS_UNAVAILABLE", error: "Payment status unavailable" }, 503);
        if (!data) return json({ success: false, found: false, code: "PAYMENT_NOT_FOUND", error: "Payment not found" }, 404);
        const recovered = await recoverPayment(deps, data);
        return json(outcome(recovered.payment, recovered.persistenceError ? "RECEIPT_UPDATE_PENDING" : undefined));
      }
      if (req.method === "POST" && ["otp-send", "otp-verify", "link-signin"].includes(action)) {
        return json({ success: false, code: "IN_APP_LINK_APPROVAL_REQUIRED", error: "Approve Platinum Circles in IntoBank, then enter the linking code here." }, 410);
      }
      if (req.method === "GET" && ["balance", "status", "peer-status"].includes(action)) {
        let externalUser = user.id;
        if (action === "peer-status") {
          externalUser = url.searchParams.get("user") || "";
          if (!uuid(externalUser)) return json({ success: false, error: "Valid user required" }, 400);
          const { data, error } = await deps.db.from("conversations").select("id")
            .or(`and(user_1.eq.${user.id},user_2.eq.${externalUser}),and(user_2.eq.${user.id},user_1.eq.${externalUser})`).limit(1);
          if (error) return json({ success: false, error: "Conversation lookup unavailable" }, 503);
          if (!data?.length) return json({ success: false, error: "Conversation required" }, 403);
        }
        const params: Record<string, string> = { endpoint: action === "balance" ? "link-balance" : "link-status", external_user_id: externalUser };
        if (action === "balance") {
          params.currency = url.searchParams.get("currency") || "USD";
          if (!["USD", "ZWG"].includes(params.currency)) return json({ success: false, error: "Unsupported currency" }, 400);
        }
        const { data, response } = await requestCrisp(deps, params);
        if (action === "peer-status") {
          if (!response.ok) return json({ success: false, error: "Recipient connection status unavailable" }, response.status);
          if (data?.success !== true || typeof data.linked !== "boolean") {
            return json({ success: false, code: "CRISP_BAD_RESPONSE", error: "Recipient connection status was not confirmed" }, 502);
          }
          return json({ linked: data.linked });
        }
        return json(data, response.status);
      }
      if (req.method === "POST" && ["link", "unlink"].includes(action)) {
        const body: Record<string, string> = { external_user_id: user.id };
        if (action === "link") {
          const input = await req.json();
          if (typeof input?.code !== "string" || !/^[A-F0-9]{8}$/i.test(input.code.trim())) return json({ success: false, error: "Valid 8-character approval code required" }, 400);
          body.code = input.code.trim().toUpperCase();
        }
        const { data, response } = await requestCrisp(deps, { endpoint: action === "link" ? "link" : "link-unlink" }, body);
        return json(data, response.status);
      }
      if (req.method !== "POST" || action !== "pay") return json({ success: false, error: "Unknown action" }, 404);
      const body = await req.json();
      if (!uuid(body?.recipient_id) || !uuid(body?.conversation_id) || !keyValid(body?.idempotency_key)) return json({ success: false, error: "Valid recipient, conversation and idempotency key required" }, 400);
      if (body.recipient_id === user.id) return json({ success: false, error: "Cannot send to yourself" }, 400);
      const amount = Number(body.amount);
      if (!/^[0-9]+(?:\.[0-9]{1,2})?$/.test(String(body.amount)) || !(amount > 0 && amount <= 100000)) return json({ success: false, error: "Amount must be between 0.01 and 100,000 with at most two decimal places" }, 400);
      const currency = body.currency ?? "USD";
      if (!["USD", "ZWG"].includes(currency)) return json({ success: false, error: "Unsupported currency" }, 400);
      if ((body.note != null && (typeof body.note !== "string" || body.note.length > 500)) || (body.listing_id != null && !uuid(body.listing_id)) || (body.order_id != null && !uuid(body.order_id))) return json({ success: false, error: "Invalid payment details" }, 400);
      const conversation = await deps.db.from("conversations").select("id,user_1,user_2").eq("id", body.conversation_id).maybeSingle();
      if (conversation.error) return json({ success: false, error: "Conversation lookup unavailable" }, 503);
      if (!conversation.data) return json({ success: false, error: "Conversation not found" }, 404);
      if (![conversation.data.user_1, conversation.data.user_2].includes(user.id) || ![conversation.data.user_1, conversation.data.user_2].includes(body.recipient_id)) return json({ success: false, error: "Not a participant in this conversation" }, 403);
      const existing = async () => deps.db.from("chat_payments").select(PAYMENT_FIELDS).eq("sender_id", user.id).eq("idempotency_key", body.idempotency_key).maybeSingle();
      const prior = await existing();
      if (prior.error) return json({ success: false, error: "Payment lookup unavailable" }, 503);
      const returnPrior = async (payment: Payment) => {
        if (!sameIntent(payment, body)) return json({ success: false, code: "IDEMPOTENCY_CONFLICT", error: "This payment key belongs to different payment details" }, 409);
        const recovered = await recoverPayment(deps, payment);
        return json({ ...outcome(recovered.payment, recovered.persistenceError ? "RECEIPT_UPDATE_PENDING" : undefined), idempotent: true });
      };
      if (prior.data) return await returnPrior(prior.data);
      if (body.listing_id && !body.order_id) return json({ success: false, submitted: false, code: "MARKET_ORDER_REQUIRED", error: "Open an accepted marketplace order before paying for this listing" }, 409);
      // Current Crisp P2P supports USD only. Existing records remain readable and
      // recoverable in their original denomination, without creating new ZWG work.
      if (currency !== "USD") return json({ success: false, submitted: false, code: "UNSUPPORTED_CHAT_CURRENCY", error: "Chat transfers currently support USD only" }, 400);
      if (!deps.crispKey || !deps.crispUrl) return json({ success: false, code: "CRISP_UNAVAILABLE", error: "Payment service unavailable" }, 503);
      const inserted = await deps.db.from("chat_payments").insert({
        conversation_id: body.conversation_id, sender_id: user.id, recipient_id: body.recipient_id,
        idempotency_key: body.idempotency_key, amount, currency, listing_id: body.listing_id ?? null, order_id: body.order_id ?? null,
        note: body.note ?? null, status: "pending",
      }).select(PAYMENT_FIELDS).single();
      if (inserted.error?.code === "23505") {
        const raced = await existing();
        if (!raced.error && raced.data) return await returnPrior(raced.data);
        return json({ success: true, status: "pending", pending: true, code: "PAYMENT_LOOKUP_PENDING" }, 202);
      }
      if (inserted.error || !inserted.data) {
        const reason = String(inserted.error?.message || "");
        const code = ["MARKET_ORDER_REQUIRED", "ORDER_PAYMENT_MISMATCH", "ORDER_NOT_PAYABLE"].find(value => reason.includes(value));
        if (code) return json({ success: false, submitted: false, code, error: "The order cannot be paid with these details. Refresh the order before trying again." }, 409);
        return json({ success: false, error: "Could not record payment request" }, 503);
      }
      inFlight = inserted.data;
      const { data, response } = await requestCrisp(deps, { endpoint: "p2p" }, {
        sender_external_id: user.id, recipient_external_id: body.recipient_id, amount, currency,
        partner_reference: inFlight!.id, note: body.note ?? "Platinum Circles",
      });
      if (response.ok && matchesReceipt(inFlight!, data)) {
        const updated = await persistOutcome(deps, inFlight!, { status: "completed", tx_id: data.tx_id, error: null });
        return json(outcome(updated.payment, updated.persistenceError ? "RECEIPT_UPDATE_PENDING" : undefined), updated.payment.status === "pending" ? 202 : 200);
      }
      // Only an explicit no-movement rejection is definitive. Generic RPC/HTTP errors
      // can follow a committed debit and remain pending until canonical recovery.
      if (response.status >= 400 && response.status < 500 && data?.success === false && data?.confirmed_not_sent === true) {
        const updated = await persistOutcome(deps, inFlight!, { status: "failed", tx_id: null, error: "Payment declined by the payment provider" });
        return json(outcome(updated.payment, updated.persistenceError ? "RECEIPT_UPDATE_PENDING" : undefined), updated.payment.status === "pending" ? 202 : 200);
      }
      return json(outcome(inFlight!, "PAYMENT_OUTCOME_UNCONFIRMED"), 202);
    } catch (e) {
      if (inFlight) return json(outcome(inFlight, "PAYMENT_OUTCOME_UNCONFIRMED"), 202);
      // The cause is logged and named: an outage on the way to IntoBank must never read as "not linked".
      const hop = e instanceof CrispHopError ? e : null;
      let action = ""; try { action = new URL(req.url).searchParams.get("action") || ""; } catch { /* no url */ }
      console.error("[crisp-bridge]", action, hop?.code || (e as Error)?.name || "Error", (e as Error)?.message || String(e));
      return json({ success: false, code: hop?.code || "SERVICE_UNAVAILABLE", error: hop?.message || "Service temporarily unavailable" }, 503);
    }
  };
}

import { serveBusinessRequest } from '../_shared/serveBusinessRequest.ts';
// Keep credentials on the server. User identity is verified in the handler.
import { createClient } from "npm:@supabase/supabase-js@2.112.3";
import { createBridgeHandler } from "./handler.ts";

serveBusinessRequest(createBridgeHandler({
  db: createClient(Deno.env.get("SUPABASE_URL")!, Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!, {
    auth: { persistSession: false, autoRefreshToken: false },
  }),
  crispUrl: Deno.env.get("CRISP_API_URL") || "",
  crispKey: Deno.env.get("CRISP_API_KEY") || "",
  fetcher: fetch,
}));

// Shared by user status and the service-only worker. Recovery never sends money.
export type Payment = {
  id: string; sender_id: string; recipient_id: string; conversation_id: string;
  idempotency_key: string; amount: number | string; currency: string;
  listing_id: string | null; order_id?: string | null; note: string | null;
  status: "pending" | "completed" | "failed"; tx_id: string | null; error: string | null;
};
export const PAYMENT_FIELDS = "id,sender_id,recipient_id,conversation_id,idempotency_key,amount,currency,listing_id,order_id,note,status,tx_id,error";
// SDK injection allows offline tests of the actual production handler.
export type Dependencies = {
  db: any; crispUrl: string; crispKey: string; fetcher: typeof fetch; now?: () => Date; deadlineAt?: number;
};
export function outcome(payment: Payment, code?: string) {
  return {
    success: true, found: true, status: payment.status, pending: payment.status === "pending",
    payment_id: payment.id, tx_id: payment.tx_id,
    ...(payment.status === "failed" ? { error: payment.error || "Payment declined" } : {}),
    ...(code ? { code } : {}),
  };
}
export class CrispHopError extends Error {
  code: string;
  constructor(code: string, message: string) { super(message); this.code = code; this.name = "CrispHopError"; }
}
const isTimeout = (e: unknown) => { const n = (e as { name?: string } | null)?.name; return n === "TimeoutError" || n === "AbortError"; };
export async function requestCrisp(deps: Dependencies, params: Record<string, string>, body?: unknown) {
  // Every failure on the hop to IntoBank's payment service names itself, so an outage is never
  // mistaken for an unlinked account and the cause is readable in the logs and on the phone.
  if (!deps.crispKey || !deps.crispUrl) throw new CrispHopError("CRISP_NOT_CONFIGURED", "IntoBank's payment service is not configured on this server.");
  let url: URL;
  try { url = new URL(deps.crispUrl); } catch { throw new CrispHopError("CRISP_NOT_CONFIGURED", "IntoBank's payment service address is not valid on this server."); }
  if (url.protocol !== "https:" && !(url.protocol === "http:" && ["localhost", "127.0.0.1", "host.docker.internal"].includes(url.hostname))) throw new CrispHopError("CRISP_NOT_CONFIGURED", "IntoBank's payment service address is not secure.");
  for (const [key, value] of Object.entries(params)) url.searchParams.set(key, value);
  const isRead = body === undefined;
  // One total deadline covers retries and the response body. A worker can pass
  // its remaining budget so a final request cannot outlive the batch deadline.
  const budget = Math.min(isRead ? 12000 : 7000, (deps.deadlineAt ?? Infinity) - Date.now());
  if (budget <= 0) throw new CrispHopError("CRISP_TIMEOUT", "IntoBank's payment service did not answer in time.");
  const signal = AbortSignal.timeout(Math.ceil(budget));
  const attempt = () => deps.fetcher(url, {
    method: isRead ? "GET" : "POST",
    headers: { Authorization: `Bearer ${deps.crispKey}`, "Content-Type": "application/json" },
    ...(isRead ? {} : { body: JSON.stringify(body) }),
    signal,
  });
  let response: Response;
  try {
    response = await attempt();
  } catch (first) {
    // A read is safe to ask again: a cold start on the IntoBank side can outlast the first deadline. A payment is not retried here.
    if (!isRead || signal.aborted) throw new CrispHopError(isTimeout(first) || signal.aborted ? "CRISP_TIMEOUT" : "CRISP_UNREACHABLE", "IntoBank's payment service did not answer.");
    try { response = await attempt(); }
    catch (second) { throw new CrispHopError(isTimeout(second) ? "CRISP_TIMEOUT" : "CRISP_UNREACHABLE", isTimeout(second) ? `IntoBank's payment service at ${url.host} did not answer in time.` : `IntoBank's payment service at ${url.host} could not be reached.`); }
  }
  const text = await response.text();
  let data: unknown;
  try { data = text ? JSON.parse(text) : {}; }
  catch { throw new CrispHopError("CRISP_BAD_RESPONSE", `IntoBank's payment service at ${url.host} answered status ${response.status} without a readable body.`); }
  return { response, data: data as any };
}
export function matchesReceipt(payment: Payment, data: any): boolean {
  return data?.success === true && typeof data.tx_id === "string" &&
    /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(data.tx_id) &&
    data.partner_reference === payment.id && data.currency === payment.currency &&
    (typeof data.amount === "number" || typeof data.amount === "string") &&
    /^[0-9]+(?:\.[0-9]{1,2})?$/.test(String(data.amount)) &&
    Number.isFinite(Number(data.amount)) && Number(data.amount) > 0 &&
    Number(data.amount) === Number(payment.amount);
}
export async function persistOutcome(deps: Dependencies, payment: Payment,
  next: { status: "completed" | "failed"; tx_id: string | null; error: string | null }) {
  const { data, error } = await deps.db.from("chat_payments").update({
    ...next, completed_at: next.status === "completed" ? (deps.now?.() || new Date()).toISOString() : null,
  }).eq("id", payment.id).eq("status", "pending").select(PAYMENT_FIELDS).maybeSingle();
  // An error or zero-row write cannot manufacture a completed local receipt.
  if (error) return { payment, persistenceError: true };
  if (data) return { payment: data as Payment, persistenceError: false };
  const latest = await deps.db.from("chat_payments").select(PAYMENT_FIELDS).eq("id", payment.id).maybeSingle();
  if (latest.error || !latest.data) return { payment, persistenceError: true };
  return { payment: latest.data as Payment, persistenceError: false };
}
export async function recoverPayment(deps: Dependencies, payment: Payment) {
  if (payment.status !== "pending") return { payment, persistenceError: false, lookupError: false, lookupAttempted: false };
  // Atomically claim one minute of recovery ownership. Concurrent workers and
  // status requests cannot all poll the provider for the same pending payment.
  const now = deps.now?.() || new Date();
  const cutoff = new Date(now.getTime() - 60000).toISOString();
  const touched = await deps.db.from("chat_payments").update({
    last_status_check_at: now.toISOString(),
  }).eq("id", payment.id).eq("status", "pending")
    .or(`last_status_check_at.is.null,last_status_check_at.lte.${cutoff}`)
    .select(PAYMENT_FIELDS).maybeSingle();
  if (touched.error) return { payment, persistenceError: true, lookupError: false, lookupAttempted: false };
  if (!touched.data) {
    const latest = await deps.db.from("chat_payments").select(PAYMENT_FIELDS).eq("id", payment.id).maybeSingle();
    return { payment: latest.data || payment, persistenceError: Boolean(latest.error), lookupError: false, lookupAttempted: false };
  }
  try {
    const { response, data } = await requestCrisp(deps, { endpoint: "p2p-status", partner_reference: payment.id });
    if (response.ok && data?.status === "completed" && matchesReceipt(payment, data)) {
      return { ...await persistOutcome(deps, payment, { status: "completed", tx_id: data.tx_id, error: null }), lookupAttempted: true };
    }
    // A missing transaction can be delayed or still in flight. It is not failure.
    return { payment, persistenceError: false, lookupError: !response.ok || data?.success !== true || data?.status !== "not_found", lookupAttempted: true };
  } catch {
    return { payment, persistenceError: false, lookupError: true, lookupAttempted: true };
  }
}
